export const belongingId = (number: StoryLessonNumber) => `conversational-skills-L8-C3-${number}-${belongingEpisodes[number].skill}-en-v1`;

export function buildBelongingLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, belongingEpisodes[number], previous, reference, {
    id: belongingId(number), chapterName: 'The Price of Belonging', pronunciation: belongingPronunciation[number],
    setting: 'Aokawa, a fictional Tokyo neighbourhood, including its station, Daisuke’s café, research interviews, a redevelopment information meeting and a later public community forum.',
    previousSummary: index === 0 ? closedDoorsEpisodes[9].closing : belongingEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(8)}\nReference: The Things We Don’t Say, Chapter 3: The Price of Belonging. TOEIC 785–940 visible label and owner range. Eight source episodes map to slots 1-4 and 6-9; 5/10 stay dynamic. English only, four expressions, only Step B pronunciation with precise bold stress, no Part III or extra commentary. Objective first, plain situations, separate questions, short tutor-first dialogue, private listening, fresh reading missions, standard guides and fixed English feedback. No external model APIs, app AI credits, new artwork or romance. Monday proposal announcement: housing, walkways, commerce/accessibility/investment aims, café building among possible replacements, information meeting next week, support unsettled. Developers/residents have competing perspectives, not villains versus total opposition. Yuna thirty-year-old full-time supermarket worker, rent/transport/utilities and rising housing costs, mother occasional assistance; moving hypothetical, no figures or poverty threshold. Farah Malaysian, six years in Japan, stable income/permanent job, agents report certain landlords excluding foreign applicants; manager acknowledges possible communication help, no legal finding, adopted policy or new tenancy. Kenta private education/family support; Sora paid work through university, less time for internships/extracurricular activities, not no effort/opportunity. Daisuke uncle helped find affordable location, not financed business. Mr. Hayashi fifty-eight former office manager lost job in restructuring, more than thirty applications, many unanswered, some technology/adaptation questions, training completed; age bias possible but not proven sole cause. Different person from Level 7 Ms. Hayashi lawyer. Café offer temporary administrative work, not permanent employment or guaranteed remedy. Information meeting leaves prices and relocation support open; young couple welcomes infrastructure while wanting resident voice. Later after-closing disclosure: substantial debt from kitchen renovation, sales never fully recovered, no repayment conversation with lender yet; café would struggle even without project. Suggest review/professional advice, no prescribed finance plan, amounts, bankruptcy or rescue. Explicit no podcast use, Emi agrees; this debt stays private even after general public forum remarks. A week later Riku community forum; Leila records public discussion with organisers permission and clear notices, not private-source blanket consent. Daisuke publicly acknowledges some businesses may not survive whether redevelopment happens or not, followed by practical support, fair negotiation and adaptation opportunities. Riku proposes resident advisory group for relocation review/direct concerns; Ms. Fujimoto only agrees to take suggestion back, no formed group or final agreement. Later unknown person uploads clipped statement with support/qualifying context omitted and misleading caption saying shops should accept fate. Online one hour and sharing begins, no exact views, uploader identity, motive, coordination proof or completed response. Leila’s authorised recording does not identify her as uploader. End unresolved; do not expose private debt to correct public clip or connect Akari’s confidential family business to a shared project without evidence.`,
  });
  lesson.storyData.storyTitle = 'The Things We Don’t Say';
  lesson.storyData.characters = [
    { id: 'emi', name: 'Emi Sato', role: 'main', description: 'Independent podcast journalist who explores competing perspectives, qualifies claims and preserves private boundaries during a public controversy.' },
    { id: 'riku', name: 'Riku', role: 'supporting', description: 'Community organiser who introduces residents, asks about housing and proposes a resident advisory group at the forum.' },
    { id: 'hana', name: 'Hana', role: 'supporting', description: 'Friend who discusses financial insecurity with Emi. No professional qualification or nationality is supplied.' },
    { id: 'leila', name: 'Leila', role: 'supporting', description: 'Podcast producer who records the public forum with permission and clear notices, then discovers the clipped online version.' },
    { id: 'daisuke', name: 'Daisuke', role: 'supporting', description: 'Café owner of twenty years who privately discloses renovation debt, offers temporary administrative work and publicly argues for support during change.' },
    { id: 'fujimoto', name: 'Ms. Fujimoto', role: 'supporting', description: 'Development-company representative who explains proposed benefits, acknowledges unresolved support questions and takes the advisory suggestion back for consideration.' },
    { id: 'yuna', name: 'Yuna', role: 'supporting', description: 'Thirty-year-old full-time supermarket worker facing high living costs and considering how location affects occasional assistance to her mother.' },
    { id: 'farah', name: 'Farah', role: 'supporting', description: 'Malaysian professional living in Japan for six years who describes nationality-based rental screening and requests individual consideration.' },
    { id: 'kenta', name: 'Kenta', role: 'supporting', description: 'University graduate who recognises how private education and family financial support influenced access to opportunities.' },
    { id: 'sora', name: 'Sora', role: 'supporting', description: 'University graduate who worked to cover living expenses and had less time for internships and extracurricular activities.' },
    { id: 'hayashi', name: 'Mr. Hayashi', role: 'supporting', description: 'Fifty-eight-year-old former office manager who completed training after restructuring and is offered temporary café administration work.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 8, chapter: 3, lessonNumber: number,
    levelBadge: 'TOEIC 785–940', chapterLabel: 'Chapter 3: The Price of Belonging', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 785-940', authoringLanguageRevision: 'toeic-v1' };
}

export function buildBelongingChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildBelongingLesson(number, {}, reference));
}
